import React from 'react';
import { Link, graphql, type PageProps } from 'gatsby';
import { Helmet } from 'react-helmet';
import { PROJECTS, DARK, LIGHT } from '../data';
import { usePersistentTheme } from '../hooks/usePersistentTheme';
import type { Project, Theme } from '../types';
import { Layout } from '../components/Layout';
import {
  ContentfulProjectDetails,
  type ContentfulProject,
} from '../components/ContentfulProjectDetails';

interface ProjectsPageData {
  allContentfulProject: {
    nodes: ContentfulProject[];
  };
}

interface NavProject {
  slug: string;
  name: string;
}

function getSelectedSlug(search: string): string | null {
  return new URLSearchParams(search).get('project');
}

function buildNavProjects(
  contentfulProjects: ContentfulProject[],
): NavProject[] {
  const bySlug = new Map<string, NavProject>();

  PROJECTS.forEach((project) => {
    bySlug.set(project.slug, { slug: project.slug, name: project.name });
  });

  contentfulProjects.forEach((project) => {
    if (!project.sku) return;
    bySlug.set(project.sku, {
      slug: project.sku,
      name: project.title || project.sku,
    });
  });

  return [...bySlug.values()];
}

function getContentfulProjectBySlug(
  contentfulProjects: ContentfulProject[],
  slug: string | null,
): ContentfulProject | null {
  if (!slug) return null;
  return contentfulProjects.find((project) => project.sku === slug) ?? null;
}

function getStaticProjectBySlug(slug: string | null): Project {
  const fallback = PROJECTS[0];

  if (!fallback) {
    throw new Error('PROJECTS data is empty.');
  }

  if (!slug) return fallback;
  return PROJECTS.find((project) => project.slug === slug) ?? fallback;
}

function ProjectDetails({ project, t }: { project: Project; t: Theme }) {
  const accentColor =
    project.accent === 'teal'
      ? t.teal
      : project.accent === 'amber'
        ? t.amber
        : project.accent === 'blue'
          ? t.blue
          : t.purple;

  return (
    <article
      style={{
        border: `1px solid ${t.border}`,
        borderRadius: 10,
        background: t.surface,
        padding: 28,
      }}
    >
      <h1
        style={{
          margin: '0 0 12px 0',
          fontFamily: 'Syne, sans-serif',
          fontSize: 'clamp(34px, 5vw, 56px)',
          lineHeight: 1,
          letterSpacing: '-0.03em',
          color: t.text,
        }}
      >
        {project.name}
      </h1>
      <p
        style={{
          margin: '0 0 18px 0',
          color: t.text2,
          fontSize: 14,
          lineHeight: 1.8,
          fontFamily: 'DM Mono, monospace',
        }}
      >
        {project.desc}
      </p>

      <div
        style={{
          marginBottom: 18,
          fontSize: 12,
          letterSpacing: '0.06em',
          textTransform: 'uppercase',
          color: accentColor,
          fontFamily: 'DM Mono, monospace',
        }}
      >
        {project.accent}
      </div>

      <section style={{ marginBottom: 24 }}>
        <h2
          style={{
            margin: '0 0 12px 0',
            fontFamily: 'Syne, sans-serif',
            fontSize: 24,
            color: t.text,
          }}
        >
          Tech Stack
        </h2>

        <div
          style={{
            display: 'flex',
            gap: 8,
            flexWrap: 'wrap',
            marginBottom: 18,
          }}
        >
          {project.chips.map((chip) => (
            <span
              key={chip}
              style={{
                fontSize: 10,
                padding: '4px 9px',
                borderRadius: 3,
                background: t.chipBg,
                border: `1px solid ${t.border}`,
                color: t.text3,
                letterSpacing: '0.04em',
              }}
            >
              {chip}
            </span>
          ))}
        </div>
      </section>

      <section>
        <h2
          style={{
            margin: '0 0 12px 0',
            fontFamily: 'Syne, sans-serif',
            fontSize: 24,
            color: t.text,
          }}
        >
          Highlights
        </h2>
        <ul
          style={{
            margin: 0,
            color: t.text2,
            lineHeight: 1.85,
            fontFamily: 'DM Mono, monospace',
            background: t.chipBg,
            border: `1px solid ${t.border}`,
            borderRadius: 8,
            padding: '16px 16px 16px 34px',
          }}
        >
          {project.details.map((detail) => (
            <li key={detail} style={{ marginBottom: 8 }}>
              {detail}
            </li>
          ))}
        </ul>
      </section>
    </article>
  );
}

export default function ProjectsPage({
  location,
  data,
}: PageProps<ProjectsPageData>) {
  const [isLight, toggle] = usePersistentTheme();
  const t: Theme = isLight ? LIGHT : DARK;
  const contentfulProjects = data?.allContentfulProject?.nodes ?? [];
  const navProjects = buildNavProjects(contentfulProjects);
  const fallbackSlug = navProjects[0]?.slug ?? PROJECTS[0]?.slug ?? null;
  const selectedSlug = getSelectedSlug(location.search) ?? fallbackSlug;
  const selectedContentful = getContentfulProjectBySlug(
    contentfulProjects,
    selectedSlug,
  );
  const selectedStatic = getStaticProjectBySlug(selectedSlug);

  return (
    <>
      <Helmet>
        <html lang='en' />
        <title>Projects · Sanjeera Di</title>
        <meta
          name='description'
          content='Project details for selected software projects by Sanjeera Di.'
        />
      </Helmet>

      <Layout t={t} isLight={isLight} toggle={toggle}>
        <div
          className='cv-inner projects-page-inner'
          style={{ padding: '120px clamp(20px, 5vw, 48px) 80px' }}
        >
          <div
            className='projects-page-topbar'
            style={{
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
              marginBottom: 24,
            }}
          >
            <Link
              to='/#projects'
              style={{
                color: t.text2,
                fontSize: 12,
                letterSpacing: '0.06em',
                textDecoration: 'none',
                fontFamily: 'DM Mono, monospace',
              }}
            >
              {'<- back home'}
            </Link>
          </div>

          <div
            className='projects-page-grid'
            style={{
              display: 'grid',
              gridTemplateColumns: 'minmax(220px, 260px) minmax(0, 1fr)',
              gap: 20,
            }}
          >
            <aside
              className='projects-page-aside'
              style={{
                border: `1px solid ${t.border}`,
                borderRadius: 10,
                background: t.surface,
                padding: 16,
                alignSelf: 'start',
              }}
            >
              <div
                style={{
                  fontFamily: 'DM Mono, monospace',
                  fontSize: 11,
                  letterSpacing: '0.12em',
                  textTransform: 'uppercase',
                  color: t.text3,
                  marginBottom: 12,
                }}
              >
                Projects
              </div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                {navProjects.map((project) => {
                  const active = selectedSlug === project.slug;
                  return (
                    <Link
                      key={project.slug}
                      to={`/projects/?project=${encodeURIComponent(project.slug)}`}
                      style={{
                        textDecoration: 'none',
                        fontSize: 12,
                        color: active ? t.text : t.text2,
                        border: `1px solid ${active ? t.purple : t.border}`,
                        background: active ? t.purpleDim : 'transparent',
                        borderRadius: 6,
                        padding: '10px 12px',
                        transition: 'all 0.2s',
                      }}
                    >
                      {project.name}
                    </Link>
                  );
                })}
              </div>
            </aside>

            {selectedContentful ? (
              <div className='projects-page-detail'>
                <ContentfulProjectDetails project={selectedContentful} t={t} />
              </div>
            ) : (
              <div className='projects-page-detail'>
                <ProjectDetails project={selectedStatic} t={t} />
              </div>
            )}
          </div>
        </div>
      </Layout>
    </>
  );
}

export const query = graphql`
  query ProjectsPageQuery {
    allContentfulProject {
      nodes {
        id
        sku
        title
        introduction
        price
        description {
          raw
        }
        headerImage {
          gatsbyImageData(
            width: 2000
            placeholder: BLURRED
            formats: [AUTO, WEBP, AVIF]
          )
        }
        gallery {
          title
          description
          gatsbyImageData(
            width: 1000
            placeholder: BLURRED
            formats: [AUTO, WEBP, AVIF]
          )
        }
      }
    }
  }
`;
